// === Tab: Terrain.js ===
class Terrain {
  constructor(params) {
    this.size = params.terrainSize;
    this.area = this.size * this.size;
    this.params = params;

    this.heightMap = new Float32Array(this.area);
    this.originalHeightMap = new Float32Array(this.area);

    this.bedrockMap = new Float32Array(this.area);
    this.sedimentMap = new Float32Array(this.area);

    this.dischargeMap = new Float32Array(this.area);
    this.dischargeTrack = new Float32Array(this.area);

    this.momentumX = new Float32Array(this.area);
    this.momentumY = new Float32Array(this.area);
    this.momentumXTrack = new Float32Array(this.area);
    this.momentumYTrack = new Float32Array(this.area);

    this.sharedNormal = { x: 0, y: 0, z: 0 };
  }

  getIndex(x, y) {
    return y * this.size + x;
  }

  getHeight(x, y) {
    if (x < 0 || x >= this.size || y < 0 || y >= this.size) return 0;
    return this.heightMap[y * this.size + x];
  }

  updateTotalHeight(index) {
    this.heightMap[index] = this.bedrockMap[index] + this.sedimentMap[index];
  }

  getMapBounds(mapArray) {
    let minVal = Infinity;
    let maxVal = -Infinity;

    for (let i = 0; i < mapArray.length; i++) {
      const value = mapArray[i];
      if (value < minVal) minVal = value;
      if (value > maxVal) maxVal = value;
    }

    return { min: minVal, max: maxVal };
  }

  getSurfaceNormal(x, y) {
    const { size, heightMap, sharedNormal, params } = this;
    const { heightScale } = params;

    const westIndex = x > 0 ? y * size + (x - 1) : y * size + x;
    const eastIndex = x < size - 1 ? y * size + (x + 1) : y * size + x;
    const northIndex = y > 0 ? (y - 1) * size + x : y * size + x;
    const southIndex = y < size - 1 ? (y + 1) * size + x : y * size + x;

    const deltaX = (heightMap[westIndex] - heightMap[eastIndex]) * heightScale;
    const deltaZ = (heightMap[northIndex] - heightMap[southIndex]) * heightScale;
    const deltaY = 1.0;

    const magnitude = Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);

    sharedNormal.x = deltaX / magnitude;
    sharedNormal.y = deltaY / magnitude;
    sharedNormal.z = deltaZ / magnitude;

    return sharedNormal;
  }

  getDischarge(index) {
    const intensity = this.dischargeMap[index];
    return this.codyErf(0.4 * intensity);
  }

  codyErf(x) {
    const absX = Math.abs(x);
    if (absX > 9.3) return x > 0 ? 1.0 : -1.0;

    let result;
    if (absX <= 0.84375) {
      const xSq = x * x;
      const p = [3.1611237438705656, 113.86415415105016, 377.485237685302, 3209.3775891384695, 0.18577770618460315];
      const q = [23.601290953873412, 244.55303442692948, 1287.1751860847748, 2844.2368334391706];

      const numerator = (((p[4] * xSq + p[0]) * xSq + p[1]) * xSq + p[2]) * xSq + p[3];
      const denominator = (((xSq + q[0]) * xSq + q[1]) * xSq + q[2]) * xSq + q[3];

      result = x * (numerator / denominator);
    } else if (absX <= 4.0) {
      var p = [0.5641884969886701, 8.883149794388376, 66.11542093743808, 298.63513819740013, 881.9522212417691, 1712.0476126340706, 2051.0783778260715, 1230.3393547979972, 2.1531153547440385e-8];
      var q = [15.744926110709835, 117.6939508913125, 537.1811018620099, 1621.3895745386784, 3290.7992357334596, 4362.61909014206, 3439.3676741437216, 1230.3393548037443];

      const n = (((((((p[8] * absX + p[0]) * absX + p[1]) * absX + p[2]) * absX + p[3]) * absX + p[4]) * absX + p[5]) * absX + p[6]) * absX + p[7];
      const d = (((((((absX + q[0]) * absX + q[1]) * absX + q[2]) * absX + q[3]) * absX + q[4]) * absX + q[5]) * absX + q[6]) * absX + q[7];

      result = 1.0 - Math.exp(-x * x) * (n / d);
      if (x < 0) result = -result;
    } else {
      result = x > 0 ? 1.0 : -1.0;
    }
    return result;
  }

  generate() {
    const { noiseScale, noiseOctaves, amplitudeFalloff } = this.params;
    const { size, area, heightMap, originalHeightMap, bedrockMap, sedimentMap, dischargeMap, dischargeTrack, momentumX, momentumY, momentumXTrack, momentumYTrack } = this;

    const maps = [heightMap, originalHeightMap, bedrockMap, sedimentMap, dischargeMap, dischargeTrack, momentumX, momentumY, momentumXTrack, momentumYTrack];
    maps.forEach(map => map.fill(0));

    const octaveOffsets = [];
    for (let i = 0; i < noiseOctaves; i++) {
      octaveOffsets.push({ x: random(100000), y: random(100000) });
    }

    for (let i = 0; i < area; i++) {
      const x = i % size;
      const y = (i / size) | 0;

      let currentAmplitude = 1;
      let currentFrequency = noiseScale / 100;
      let accumulatedNoise = 0;

      for (let octave = 0; octave < noiseOctaves; octave++) {
        const sampleX = x * currentFrequency + octaveOffsets[octave].x;
        const sampleY = y * currentFrequency + octaveOffsets[octave].y;

        accumulatedNoise += noise(sampleX, sampleY) * currentAmplitude;
        currentFrequency *= 2;
        currentAmplitude *= amplitudeFalloff;
      }

      heightMap[i] = Math.pow(accumulatedNoise, 1.2);
    }

    const { min: minH, max: maxH } = this.getMapBounds(heightMap);
    const heightRange = maxH - minH || 1;

    for (let i = 0; i < area; i++) {
      const normalisedHeight = (heightMap[i] - minH) / heightRange;
      heightMap[i] = normalisedHeight;
      bedrockMap[i] = normalisedHeight;
      originalHeightMap[i] = normalisedHeight;
    }
  }

  reset() {
    [this.heightMap, this.bedrockMap].forEach(map => map.set(this.originalHeightMap));
    [this.sedimentMap, this.dischargeMap, this.dischargeTrack, this.momentumX, this.momentumY, this.momentumXTrack, this.momentumYTrack].forEach(map => map.fill(0));
  }
}

// === Tab: Solver.js ===
class Solver {
  constructor(terrain, params) {
    this.terrain = terrain;
    this.params = params;

    const SQRT2 = Math.SQRT2;
    this.neighbours = [
      { x: -1, y: -1, distance: SQRT2 }, { x: -1, y: 0, distance: 1 }, { x: -1, y: 1, distance: SQRT2 },
      { x: 0, y: -1, distance: 1 },                                  { x: 0, y: 1, distance: 1 },
      { x: 1, y: -1, distance: SQRT2 },  { x: 1, y: 0, distance: 1 },  { x: 1, y: 1, distance: SQRT2 },
    ];
  }

  updateDischargeMap() {
    const { learningRate } = this.params;
    const { area, dischargeMap, dischargeTrack, momentumX, momentumXTrack, momentumY, momentumYTrack } = this.terrain;
    const inverseLearningRate = 1.0 - learningRate;

    for (let i = 0; i < area; i++) {
      dischargeMap[i] = inverseLearningRate * dischargeMap[i] + learningRate * dischargeTrack[i];
      momentumX[i] = inverseLearningRate * momentumX[i] + learningRate * momentumXTrack[i];
      momentumY[i] = inverseLearningRate * momentumY[i] + learningRate * momentumYTrack[i];
    }
  }

  hydraulicErosion() {
    const {
      dropletsPerFrame, maxAge, minVolume, precipitationRate,
      gravity, momentumTransfer, entrainment, depositionRate,
      evaporationRate, sedimentErosionRate, bedrockErosionRate
    } = this.params;

    var terrain = this.terrain;
    const { size } = terrain;

    terrain.dischargeTrack.fill(0);
    terrain.momentumXTrack.fill(0);
    terrain.momentumYTrack.fill(0);

    for (let d = 0; d < dropletsPerFrame; d++) {
      var x = random(size) | 0;
      var y = random(size) | 0;

      if (terrain.getHeight(x, y) < 0.1) continue;

      let vx = 0;
      let vy = 0;
      let sediment = 0;
      let age = 0;
      let volume = precipitationRate;

      while (age < maxAge && volume >= minVolume) {
        const floorX = x | 0;
        const floorY = y | 0;

        if (floorX < 0 || floorX >= size || floorY < 0 || floorY >= size) break;

        const index = terrain.getIndex(floorX, floorY);
        const heightStart = terrain.heightMap[index];
        const normal = terrain.getSurfaceNormal(floorX, floorY);

        vx += (gravity * normal.x) / volume;
        vy += (gravity * normal.z) / volume;

        const prevMomentumX = terrain.momentumX[index];
        const prevMomentumY = terrain.momentumY[index];
        const prevMomentumMag = Math.sqrt(prevMomentumX * prevMomentumX + prevMomentumY * prevMomentumY);

        if (prevMomentumMag > 0) {
          const currentSpeed = Math.sqrt(vx * vx + vy * vy);
          if (currentSpeed > 0) {
            const alignment = (prevMomentumX * vx + prevMomentumY * vy) / (prevMomentumMag * currentSpeed);
            const transfer = (momentumTransfer * alignment) / (volume + terrain.dischargeMap[index]);
            vx += transfer * prevMomentumX;
            vy += transfer * prevMomentumY;
          }
        }

        const finalSpeed = Math.sqrt(vx * vx + vy * vy);
        if (finalSpeed > 0) {
          var magnitude = Math.SQRT2 / finalSpeed;
          vx *= magnitude;
          vy *= magnitude;
        }

        x += vx;
        y += vy;

        terrain.dischargeTrack[index] += volume;
        terrain.momentumXTrack[index] += volume * vx;
        terrain.momentumYTrack[index] += volume * vy;

        const isOutOfBounds = (x < 0 || x >= size || y < 0 || y >= size);
        const heightEnd = isOutOfBounds ? heightStart - 0.002 : terrain.getHeight(x | 0, y | 0);

        const transportCapacity = Math.max(0, (1 + entrainment * terrain.getDischarge(index)) * (heightStart - heightEnd));
        const sedimentDeficit = transportCapacity - sediment;

        if (sedimentDeficit > 0) {
          const fromSediment = Math.min(terrain.sedimentMap[index], sedimentDeficit * sedimentErosionRate);
          terrain.sedimentMap[index] -= fromSediment;

          let actualErosion = fromSediment;
          const remainingDeficit = (sedimentDeficit - (fromSediment / sedimentErosionRate));

          if (remainingDeficit > 0) {
            const fromBedrock = remainingDeficit * bedrockErosionRate;
            terrain.bedrockMap[index] -= fromBedrock;
            actualErosion += fromBedrock;
          }

          sediment += actualErosion;
        } else {
          const deposited = -sedimentDeficit * depositionRate;
          terrain.sedimentMap[index] += deposited;
          sediment -= deposited;
        }

        terrain.updateTotalHeight(index);

        const evaporation = (1 - evaporationRate);
        volume *= evaporation;
        sediment *= evaporation;

        if (isOutOfBounds) break;

        this.thermalErosion(x, y);
        age++;
      }
    }
  }

  thermalErosion(x, y) {
    const { size, heightMap, sedimentMap, bedrockMap } = this.terrain;
    const { maxHeightDiff, settlingRate } = this.params;
    var terrain = this.terrain;

    const centerX = x | 0;
    const centerY = y | 0;

    if (centerX < 0 || centerX >= size || centerY < 0 || centerY >= size) return;

    const centerIndex = terrain.getIndex(centerX, centerY);
    const centerHeight = heightMap[centerIndex];

    for (let i = 0; i < this.neighbours.length; i++) {
      const neighbour = this.neighbours[i];
      const nx = centerX + neighbour.x;
      const ny = centerY + neighbour.y;

      if (nx < 0 || nx >= size || ny < 0 || ny >= size) continue;

      const neighbourIndex = terrain.getIndex(nx, ny);
      const neighbourHeight = heightMap[neighbourIndex];
      const heightDifference = centerHeight - neighbourHeight;

      if (heightDifference === 0) continue;

      const absoluteDifference = Math.abs(heightDifference);
      const excess = absoluteDifference - neighbour.distance * maxHeightDiff;

      if (excess <= 0) continue;

      const transferValue = (settlingRate * excess) / 2;
      const sourceIndex = heightDifference > 0 ? centerIndex : neighbourIndex;
      const targetIndex = heightDifference > 0 ? neighbourIndex : centerIndex;

      heightMap[sourceIndex] -= transferValue;
      heightMap[targetIndex] += transferValue;

      let remainingToTransfer = transferValue;
      var fromSediment = Math.min(remainingToTransfer, sedimentMap[sourceIndex]);

      sedimentMap[sourceIndex] -= fromSediment;
      remainingToTransfer -= fromSediment;

      if (remainingToTransfer > 0) {
        bedrockMap[sourceIndex] -= remainingToTransfer;
      }
      sedimentMap[targetIndex] += transferValue;
    }
  }
}

// === Tab: Renderer.js ===
class Renderer {
  constructor(terrain, params, cameraData, gestureData, vertShader, fragShader, colourMaps) {
    this.terrain = terrain;
    this.params = params;
    this.cameraData = cameraData;
    this.gestureData = gestureData;
    this.colourMaps = colourMaps;

    this.canvas3D = createGraphics(width, height, WEBGL);
    this.terrainShader = this.canvas3D.createShader(vertShader, fragShader);

    this.canvas2D = createImage(terrain.size, terrain.size);
    this.heightMapTexture = createImage(terrain.size, terrain.size);

    this.lut = new Uint8ClampedArray(256 * 3);
    this.currentColourMap = "";
  }

  updateLUT(colourMap) {
    if (this.currentColourMap === colourMap) return;

    this.currentColourMap = colourMap;
    const colourData = this.colourMaps[colourMap];
    if (!colourData) return;

    const channels = ["r", "g", "b"];

    for (let i = 0; i < 256; i++) {
      const intensity = i / 255;
      const offset = i * 3;

      for (let c = 0; c < 3; c++) {
        const coeffs = colourData[channels[c]];
        let val = 0;

        for (let j = coeffs.length - 1; j >= 0; j--) {
          val = val * intensity + coeffs[j];
        }

        this.lut[offset + c] = Math.max(0, Math.min(255, val * 255));
      }
    }
  }

  generateTextures(is3D) {
    const { 
      surfaceMap, colourMap, lightDir, flatColour, steepColour, 
      sedimentColour, waterColour, skyColour, specularIntensity 
    } = this.params;

    const { terrain, canvas2D, heightMapTexture, lut, cameraData } = this;
    const { size, area, heightMap, sedimentMap, originalHeightMap } = terrain;

    if (surfaceMap !== "composite") {
      this.updateLUT(colourMap || "greyscale");
    }

    const lightMag = Math.sqrt(lightDir.x ** 2 + lightDir.y ** 2 + lightDir.z ** 2) || 1;
    const lightX = lightDir.x / lightMag;
    const lightY = lightDir.y / lightMag;
    const lightZ = lightDir.z / lightMag;

    const viewX = is3D ? cos(cameraData.rotX) * sin(cameraData.rotZ) : 0;
    const viewY = is3D ? cos(cameraData.rotX) * cos(cameraData.rotZ) : 1;
    const viewZ = is3D ? sin(cameraData.rotX) : 0;

    const bounds = this.calculateBounds(surfaceMap);

    canvas2D.loadPixels();
    heightMapTexture.loadPixels();

    for (let i = 0; i < area; i++) {
      const pixelIndex = i << 2;
      const heightByte = (heightMap[i] * 255) | 0;

      heightMapTexture.pixels[pixelIndex] = heightMapTexture.pixels[pixelIndex + 1] = heightMapTexture.pixels[pixelIndex + 2] = heightByte;
      heightMapTexture.pixels[pixelIndex + 3] = 255;

      let r, g, b;

      if (surfaceMap === "composite") {
        var x = i % size;
        var y = (i / size) | 0;
        var normal = terrain.getSurfaceNormal(x, y);

        const dotProduct = normal.x * lightX + normal.y * lightY + normal.z * lightZ;
        const diffuse = Math.max(0, dotProduct);

        const skyWeight = normal.y * 0.5 + 0.5; 
        const shadingR = diffuse + (skyColour.r / 255) * skyWeight * 0.15;
        const shadingG = diffuse + (skyColour.g / 255) * skyWeight * 0.15;
        const shadingB = diffuse + (skyColour.b / 255) * skyWeight * 0.15;

        const steepness = 1 - normal.y;
        const flatness = 1 - steepness;

        r = (flatness * flatColour.r + steepness * steepColour.r) * shadingR;
        g = (flatness * flatColour.g + steepness * steepColour.g) * shadingG;
        b = (flatness * flatColour.b + steepness * steepColour.b) * shadingB;

        var sediment = sedimentMap[i];
        if (sediment > 0) {
          const sedimentAlpha = Math.min(1, sediment * 5);
          r = (1 - sedimentAlpha) * r + sedimentAlpha * (sedimentColour.r * shadingR);
          g = (1 - sedimentAlpha) * g + sedimentAlpha * (sedimentColour.g * shadingG);
          b = (1 - sedimentAlpha) * b + sedimentAlpha * (sedimentColour.b * shadingB);
        }

        const discharge = terrain.getDischarge(i);
        if (discharge > 0) {
          const dischargeAlpha = Math.min(1, discharge);
          const dischargeShade = Math.max(0.3, 1 - discharge * 0.25);

          r = (1 - dischargeAlpha) * r + dischargeAlpha * (waterColour.r * dischargeShade * shadingR);
          g = (1 - dischargeAlpha) * g + dischargeAlpha * (waterColour.g * dischargeShade * shadingG);
          b = (1 - dischargeAlpha) * b + dischargeAlpha * (waterColour.b * dischargeShade * shadingB);

          if (is3D) {
            const halfX = lightX + viewX;
            const halfY = lightY + viewY;
            const halfZ = lightZ + viewZ;
            const halfMag = Math.sqrt(halfX * halfX + halfY * halfY + halfZ * halfZ) || 1;

            const normalDotHalf = Math.max(0, normal.x * (halfX / halfMag) + normal.y * (halfY / halfMag) + normal.z * (halfZ / halfMag));

            const specularShine = Math.pow(normalDotHalf, 120.0) * (specularIntensity || 255) * dischargeAlpha;

            r = Math.min(255, r + specularShine);
            g = Math.min(255, g + specularShine);
            b = Math.min(255, b + specularShine);
          }
        }
      } else {
        var value = 0;
        if (surfaceMap === "height") {
          value = (heightMap[i] - bounds.min) / bounds.range;
        } else if (surfaceMap === "slope") {
          value = 1 - terrain.getSurfaceNormal(i % size, (i / size) | 0).y;
        } else if (surfaceMap === "discharge") {
          value = terrain.getDischarge(i) / bounds.range;
        } else if (surfaceMap === "sediment") {
          value = (sedimentMap[i] - bounds.min) / bounds.range;
        } else if (surfaceMap === "delta") {
          value = 0.5 + (heightMap[i] - originalHeightMap[i]) * 10;
        }

        const lutIndex = ((value * 255) | 0) * 3;
        const safeIndex = Math.max(0, Math.min(765, lutIndex));

        r = lut[safeIndex]; 
        g = lut[safeIndex + 1]; 
        b = lut[safeIndex + 2];
      }

      canvas2D.pixels[pixelIndex] = r;
      canvas2D.pixels[pixelIndex + 1] = g;
      canvas2D.pixels[pixelIndex + 2] = b;
      canvas2D.pixels[pixelIndex + 3] = 255;
    }

    canvas2D.updatePixels();
    heightMapTexture.updatePixels();
  }

  render() {
	 const { displayMethod, heightScale } = this.params;

    const is3D = (displayMethod === "3D");
    this.generateTextures(is3D);

    if (is3D) {
      this.render3D(heightScale);
    } else {
      this.render2D();
    }
  }

  render2D() {
    image(this.canvas2D, 0, 0, width, height);
  }

  render3D(heightScale) {
    const { canvas3D, canvas2D, terrainShader, heightMapTexture, cameraData } = this;
    const { rotX, rotZ, zoom } = cameraData;
    const { skyColour } = this.params;
    const { size } = this.terrain;

    canvas3D.background(skyColour.r, skyColour.g, skyColour.b);
    canvas3D.noStroke();

    const eyeX = zoom * (cos(rotX) * sin(rotZ));
    const eyeY = zoom * (cos(rotX) * cos(rotZ));
    const eyeZ = zoom * sin(rotX);

    canvas3D.push();
    canvas3D.resetMatrix();
    canvas3D.perspective(PI / 3, width / height, 0.1, 20000);
    canvas3D.camera(eyeX, eyeY, eyeZ, 0, 0, 0, 0, 0, -1);

    canvas3D.shader(terrainShader);
    terrainShader.setUniform("uHeightMap", heightMapTexture);
    terrainShader.setUniform("uTexture", canvas2D);
    terrainShader.setUniform("uHeightScale", heightScale);

    canvas3D.plane(size * 2, size * 2, size - 1, size - 1);
    canvas3D.pop();

    image(canvas3D, 0, 0, width, height);
  }

  calculateBounds(mode) {
    const { terrain } = this;
    const { area, heightMap, sedimentMap } = terrain;

    if (mode === "height") {
      const bound = terrain.getMapBounds(heightMap);
      return { min: bound.min, range: bound.max - bound.min || 1 };
    } 

    if (mode === "discharge") {
      let maxDischarge = 0;

      for (let i = 0; i < area; i++) {
        var discharge = terrain.getDischarge(i);
        if (discharge > maxDischarge) maxDischarge = discharge;
      }

      return { min: 0, range: maxDischarge || 1 };
    } 

    if (mode === "sediment") {
      var bound = terrain.getMapBounds(sedimentMap);
      return { min: bound.min, range: bound.max - bound.min || 1 };
    }

    return { min: 0, range: 1 };
  }

  handleWheel(e) {
    this.cameraData.zoom = max(20, this.cameraData.zoom + e.delta * 0.5);
  }

  handlePointer() { 
    const { gestureData } = this;

    let points = touches.length > 0 ? touches : [];

    if (points.length === 0 && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      points = [{ x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) }];
    }

    if (points.length === 1) {
      this.handleOrbit(points[0]);
    } else if (points.length === 2) {
      this.handlePinch(points[0], points[1]);
    } else {
      gestureData.mode = null;
    }
  }

  handleOrbit(touch) {
    const { cameraData, gestureData } = this;

    if (gestureData.mode !== "orbit") {
      gestureData.mode = "orbit";
      gestureData.prevX = touch.x;
      gestureData.prevY = touch.y;
      return;
    }

    cameraData.rotZ -= (touch.x - gestureData.prevX) * 0.01;
    cameraData.rotX = constrain(cameraData.rotX + (touch.y - gestureData.prevY) * 0.01, 0.01, PI / 2);

    gestureData.prevX = touch.x;
    gestureData.prevY = touch.y;
  }

  handlePinch(t1, t2) {
    const { cameraData, gestureData } = this;
    const distance = dist(t1.x, t1.y, t2.x, t2.y);

    if (gestureData.mode !== "pinch") {
      gestureData.mode = "pinch";
      gestureData.pinchLastDist = distance;
      return;
    }

    cameraData.zoom = max(20, cameraData.zoom / (distance / gestureData.pinchLastDist));
    gestureData.pinchLastDist = distance;
  }

  resize() {
    var canvasSize = max(windowWidth, windowHeight);
    resizeCanvas(canvasSize, canvasSize);
    if (this.canvas3D) this.canvas3D.resizeCanvas(canvasSize, canvasSize);
  }
}

