class Media {
  constructor(terrain, renderer, metadata, params) {
    this.terrain = terrain;
    this.renderer = renderer;
    this.metadata = metadata;
    this.params = params;

    this.mediaRecorder = null;
    this.recordedChunks = [];
    this.isRecording = false;
  }

  _triggerDownload(url, filename) {
    const anchor = document.createElement("a");
    anchor.style.display = "none";
    anchor.href = url;
    anchor.download = filename;

    document.body.appendChild(anchor);
    anchor.click();

    setTimeout(() => {
      document.body.removeChild(anchor);
      URL.revokeObjectURL(url);
    }, 100);
  }

  _getFilename(extension) {
    const { terrainSize, surfaceMap, displayMethod } = this.params;
    const { name, version } = this.metadata;

    return `${name}_${version}_${displayMethod}_${surfaceMap}_${terrainSize}_${Date.now()}.${extension}`;
  }

  startRecording() {	  
    if (this.isRecording) return;

	 const sourceCanvas = _renderer.elt;
    if (!sourceCanvas) {
      console.error("No valid canvas found for recording");
      return;
    }

    this.recordedChunks = [];

    const supportedType =
      [
        //"video/webm;codecs=vp9",
        "video/webm;codecs=vp8",
        "video/mp4",
        "video/webm",
      ].find(type => MediaRecorder.isTypeSupported(type)) || "";

	 if (!supportedType) {
      console.error("No supported video format found for MediaRecorder");
      return;
    }

    try {
      const stream = sourceCanvas.captureStream(60);
      this.mediaRecorder = new MediaRecorder(stream, {
        mimeType: supportedType,
        videoBitsPerSecond: 8000000,
      });

      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          this.recordedChunks.push(event.data);
        }
      };

      this.mediaRecorder.onstop = () => {
        const blob = new Blob(this.recordedChunks, { type: supportedType });
        const extension = supportedType.includes("mp4") ? "mp4" : "webm";
        const filename = this._getFilename(extension);
        this._triggerDownload(URL.createObjectURL(blob), filename);
      };

      this.mediaRecorder.start();
		this.isRecording = true;

      console.log(`Recording started with type: ${supportedType}`);
    } catch (error) {
		this.stopRecording();
		this.mediaRecorder = null;	
      console.error("Failed to start recording:", error);
    }
  }

  stopRecording() {
    if (!this.mediaRecorder || !this.isRecording) return; 
	 this.mediaRecorder.stop();
	 this.isRecording = false;
	 this.recordedChunks = [];
  }

  exportCanvas() {
	 var sourceCanvas = _renderer;

	 if (!sourceCanvas) {
      console.error("No valid canvas found for export");
      return;
    }

	 try {
